func testPermissaoRecursoCampoToManyRemoveOpUfiUsuarioFilials(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a PermissaoRecursoCampo
	var b, c, d, e UsuarioFilial

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, permissaoRecursoCampoDBTypes, false, strmangle.SetComplement(permissaoRecursoCampoPrimaryKeyColumns, permissaoRecursoCampoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*UsuarioFilial{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, usuarioFilialDBTypes, false, strmangle.SetComplement(usuarioFilialPrimaryKeyColumns, usuarioFilialColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddUfiUsuarioFilials(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.UfiUsuarioFilials().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveUfiUsuarioFilials(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.UfiUsuarioFilials().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if len(b.R.PRCPPermissaoRecursoCampos) != 0 {
		t.Error("relationship was not removed properly from the slice")
	}
	if len(c.R.PRCPPermissaoRecursoCampos) != 0 {
		t.Error("relationship was not removed properly from the slice")
	}
	if d.R.PRCPPermissaoRecursoCampos[0] != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.PRCPPermissaoRecursoCampos[0] != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if len(a.R.UfiUsuarioFilials) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.UfiUsuarioFilials[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.UfiUsuarioFilials[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

func testPermissaoRecursoCampoToOnePermissaoRecursoUsingPre(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local PermissaoRecursoCampo
	var foreign PermissaoRecurso

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, permissaoRecursoCampoDBTypes, false, permissaoRecursoCampoColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize PermissaoRecursoCampo struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, permissaoRecursoDBTypes, false, permissaoRecursoColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize PermissaoRecurso struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	local.PreID = foreign.PreID
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.Pre().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if check.PreID != foreign.PreID {
		t.Errorf("want: %v, got %v", foreign.PreID, check.PreID)
	}

	ranAfterSelectHook := false
	AddPermissaoRecursoHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *PermissaoRecurso) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := PermissaoRecursoCampoSlice{&local}
	if err = local.L.LoadPre(ctx, tx, false, (*[]*PermissaoRecursoCampo)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Pre == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.Pre = nil
	if err = local.L.LoadPre(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Pre == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

func testPermissaoRecursoCampoToOneSetOpPermissaoRecursoUsingPre(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a PermissaoRecursoCampo
	var b, c PermissaoRecurso

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, permissaoRecursoCampoDBTypes, false, strmangle.SetComplement(permissaoRecursoCampoPrimaryKeyColumns, permissaoRecursoCampoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, permissaoRecursoDBTypes, false, strmangle.SetComplement(permissaoRecursoPrimaryKeyColumns, permissaoRecursoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, permissaoRecursoDBTypes, false, strmangle.SetComplement(permissaoRecursoPrimaryKeyColumns, permissaoRecursoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*PermissaoRecurso{&b, &c} {
		err = a.SetPre(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Pre != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.PrePermissaoRecursoCampos[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.PreID != x.PreID {
			t.Error("foreign key was wrong value", a.PreID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.PreID))
		reflect.Indirect(reflect.ValueOf(&a.PreID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if a.PreID != x.PreID {
			t.Error("foreign key was wrong value", a.PreID, x.PreID)
		}
	}
}

